def choose_move(observation):
    def clamp(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def first_pos(obj):
        if obj is None:
            return None
        if isinstance(obj, dict):
            for kx, ky in (("x", "y"), ("col", "row"), ("cx", "cy")):
                if kx in obj and ky in obj:
                    return [obj.get(kx), obj.get(ky)]
            for k in ("pos", "position", "loc", "location", "coord", "coords"):
                p = obj.get(k)
                if isinstance(p, (list, tuple)) and len(p) >= 2:
                    return [p[0], p[1]]
        if isinstance(obj, (list, tuple)) and len(obj) >= 2:
            if isinstance(obj[0], (int, float)) and isinstance(obj[1], (int, float)):
                return [obj[0], obj[1]]
        return None

    def find_self_pos(obs):
        for key in ("self", "agent", "me", "player", "unit", "pawn"):
            p = first_pos(obs.get(key))
            if p is not None:
                return p
        for key in ("self_pos", "agent_pos", "my_pos", "player_pos", "position", "pos"):
            p = first_pos(obs.get(key))
            if p is not None:
                return p
        # nested common structures
        for key in ("agents", "players", "units"):
            arr = obs.get(key, [])
            if isinstance(arr, (list, tuple)) and arr:
                me = arr[0]
                p = first_pos(me)
                if p is not None:
                    return p
        return [0, 0]

    def iter_positions(value):
        out = []
        if value is None:
            return out
        if isinstance(value, dict):
            p = first_pos(value)
            if p is not None:
                out.append(p)
            for v in value.values():
                out.extend(iter_positions(v))
        elif isinstance(value, (list, tuple)):
            if len(value) >= 2 and isinstance(value[0], (int, float)) and isinstance(value[1], (int, float)):
                out.append([value[0], value[1]])
            else:
                for item in value:
                    out.extend(iter_positions(item))
        return out

    def best_target(my, targets):
        best = None
        best_d = None
        for t in targets:
            dx = t[0] - my[0]
            dy = t[1] - my[1]
            d = dx * dx + dy * dy
            if best is None or d < best_d:
                best = t
                best_d = d
        return best

    def farthest_away(my, threats):
        best = None
        best_s = None
        for t in threats:
            dx = my[0] - t[0]
            dy = my[1] - t[1]
            s = dx * dx + dy * dy
            if best is None or s > best_s:
                best = t
                best_s = s
        return best

    my = find_self_pos(observation)

    # Gather likely resource/goal/territory targets
    targets = []
    for key in (
        "resources", "resource_tiles", "resource_positions", "resource_cells",
        "goals", "goal", "targets", "target", "food", "coins", "treasures",
        "territory", "capture_points", "neutral", "unowned"
    ):
        targets.extend(iter_positions(observation.get(key)))

    # Gather threats/opponents
    threats = []
    for key in (
        "enemies", "enemy", "opponents", "opponent", "adversaries", "agents", "players"
    ):
        val = observation.get(key)
        if isinstance(val, (list, tuple)):
            for item in val:
                p = first_pos(item)
                if p is not None:
                    threats.append(p)

    # If structured agents include self at index 0, ignore it
    if threats and len(threats) > 1:
        filtered = []
        for p in threats:
            if p[0] != my[0] or p[1] != my[1]:
                filtered.append(p)
        if filtered:
            threats = filtered

    # Heuristic: pursue nearest target if present; otherwise avoid nearest threat; else use center-ish drift
    tx = ty = None
    if targets:
        t = best_target(my, targets)
        tx, ty = t[0], t[1]
    elif threats:
        t = farthest_away(my, threats)
        tx, ty = my[0] + (my[0] - t[0]), my[1] + (my[1] - t[1])
    else:
        # Mild exploration bias
        grid = observation.get("grid") or observation.get("map") or observation.get("board")
        if isinstance(grid, (list, tuple)) and grid:
            h = len(grid)
            w = len(grid[0]) if isinstance(grid[0], (list, tuple)) and grid[0] else 0
            if w and h:
                tx, ty = w // 2, h // 2

    dx = dy = 0
    if tx is not None and ty is not None:
        dx = clamp(tx - my[0])
        dy = clamp(ty - my[1])

        # If threats are close, bias away from them in pursuit/territory contexts
        if threats:
            nearest = None
            nearest_d = None
            for t in threats:
                d = (t[0] - my[0]) * (t[0] - my[0]) + (t[1] - my[1]) * (t[1] - my[1])
                if nearest is None or d < nearest_d:
                    nearest = t
                    nearest_d = d
            if nearest is not None and nearest_d <= 9:
                ax = clamp(my[0] - nearest[0])
                ay = clamp(my[1] - nearest[1])
                # Prefer evasion if it conflicts strongly with target and we're in danger
                if abs(ax) > abs(dx):
                    dx = ax
                if abs(ay) > abs(dy):
                    dy = ay

    return [dx, dy]

