    h = observation.get("grid_height", 0) or 0
    sx, sy = observation.get("self_position", (0, 0))[:2]
    ox, oy = observation.get("opponent_position", (0, 0))[:2]
    res = observation.get("resources") or []
    obs = set(tuple(p[:2]) for p in (observation.get("obstacles") or []))
    sp = set(tuple(p[:2]) for p in (observation.get("self_path") or []))
    op = set(tuple(p[:2]) for p in (observation.get("opponent_path") or []))

    def step_toward(ax, ay, bx, by):
        dx = 0 if ax == bx else (1 if bx > ax else -1)
        dy = 0 if ay == by else (1 if by > ay else -1)
        if abs(bx - ax) >= abs(by - ay):
            return dx, 0
        return 0, dy

    def ok(x, y):
        return 0 <= x < w and 0 <= y < h and (x, y) not in obs

