        for cand in ((dx, dy), (dx, 0), (0, dy), (1, 0), (-1, 0), (0, 1), (0, -1), (0, 0)):
            nx, ny = sx + cand[0], sy + cand[1]
            if ok(nx, ny) and (nx, ny) not in sp:
